var QA_DIFFS_STD=[{n:'🟢 简单',d:'20题',cnt:20},{n:'🟡 中等',d:'30题',cnt:30},{n:'🔴 困难',d:'40题·答错扣5',cnt:40}];
function loadExtra(){try{var o=JSON.parse(S.getItem('bt_qa_extra')||'{}');return (o&&typeof o==='object')?o:{}}catch(e){return{}}}
function saveExtra(o){try{safeSet('bt_qa_extra',JSON.stringify(o))}catch(e){}}
function extraPool(bk){var o=loadExtra(),a=o[bk];return Array.isArray(a)?a:[]}
function addExtra(bk,list){var o=loadExtra(),cur=Array.isArray(o[bk])?o[bk]:[],seen={},add=[],man=POOLS[bk];
 if(Array.isArray(man))man.forEach(function(it){if(it&&it[0])seen[it[0]]=1});
 cur.forEach(function(x){if(x&&x.q)seen[x.q]=1});
 /* P0-5 安全闸：入库前必须过 validItem（4 选项 / 唯一 / 含答案），不合规的题直接丢弃，
    绝不出现「1 个 / 2 个选项」「答案不在选项里」的题。 */
 (list||[]).forEach(function(x){if(!validItem(x)||seen[x.q])return;seen[x.q]=1;add.push(x)});
 if(add.length){o[bk]=cur.concat(add);saveExtra(o)}return add.length}
function genStdPool(key){return function(n,diff){
 var manual=POOLS[key]||[],extra=extraPool(key);
 var src=pickPoolByDiff(manual,diff);
 /* P0-2：跨局 recent 队列 —— 优先出最近没出过的，避免「40 题做两遍」跨局也重复 */
 var _rk='bt_qa_recent_std_'+key;
 var recent=(function(){try{return JSON.parse(S.getItem(_rk)||'[]')||[]}catch(e){return[]}})();
 var recentSet={};recent.forEach(function(q){recentSet[q]=1});
 /* 1) 先无放回抽 manual（优先没出过的） */
 var ordered=shuffle(src.slice()).map(function(it){return {it:it,rec:!!recentSet[String(it[0])]}});
 ordered.sort(function(a,b){return (a.rec===b.rec)?0:(a.rec?1:-1)});
 var out=[],qseen={};
 ordered.forEach(function(c){if(out.length>=n)return;var q=String(c.it[0]);if(qseen[q])return;qseen[q]=1;out.push(mkFromPool(c.it,src));});
 /* 2) 不足则用合格 extra 补（过 validItem：含答案 / 4 选项 / 唯一；去重）；同样优先没出过的 */
 if(out.length<n&&extra.length){
  var cand=extra.filter(function(e){return validItem(e)&&(e.d==null||e.d===diff)&&!qseen[String(e.q)];});
  var recFirst=shuffle(cand.slice()).map(function(e){return {e:e,rec:!!recentSet[String(e.q)]}});
  recFirst.sort(function(a,b){return (a.rec===b.rec)?0:(a.rec?1:-1)});
  recFirst.forEach(function(c){if(out.length>=n)return;qseen[String(c.e.q)]=1;out.push({q:c.e.q,a:String(c.e.a),opts:shuffle(c.e.opts.slice()),ai:1});});
 }
 try{var nr=recent.slice();out.forEach(function(o){nr.unshift(String(o.q));});safeSet(_rk,JSON.stringify(nr.slice(0,50)));}catch(e){}
 return out}}
