// ===== 薄弱题 / 实力自适应 辅助 =====
var WEAK_CAP=150;
/* B 批：SRS 间隔复习（SM-2 简化，6 级阶梯 1/2/4/7/15/30 天） */
var SRS_INTERVALS=QALogic.SRS_INTERVALS;
function srsInit(){return QALogic.srsInit(Date.now());}
function srsDue(rec){return QALogic.srsDue(rec&&rec.srs,Date.now());}
function srsAdvance(rec,correct){
  var s=rec&&rec.srs;if(!s){rec.srs=srsInit();s=rec.srs;}
  return QALogic.srsAdvance(s,correct,Date.now());
}
/* loadWeak 每次返回新解析对象；改动某条 srs/t 后必须按 type+q 找回再存 */
function srsTouch(rec){if(!rec)return;var a=loadWeak();for(var i=0;i<a.length;i++){if(a[i]&&a[i].type===rec.type&&a[i].q===rec.q){a[i].srs=rec.srs;a[i].t=rec.t;saveWeak(a);return;}}}
function loadWeak(){
  var a;
  try{a=JSON.parse(S.getItem('bt_qa_weak')||'[]')}catch(e){a=[]}
  if(!Array.isArray(a))a=[];
  /* B 批：SRS 自愈 —— 旧条目缺 srs 字段时补上（间隔复习首屏即生效） */
  for(var _si=0;_si<a.length;_si++){if(a[_si]&&!a[_si].srs)a[_si].srs=srsInit();}
  /* 自愈：旧版本上限是 50，历史数据或异常写入可能超出 150，读的时候顺手裁一次 */
  if(a.length>WEAK_CAP){saveWeak(a);a=loadWeak();}
  return a;
}
/* P1-2：上限 50 → 150；满了按「错误次数降序 + 时间升序」裁剪，
   高频错题不会被一条只错 1 次的新题挤掉（旧版 slice(-50) 是直接砍最老的）。 */
function saveWeak(a){
  if(a.length>WEAK_CAP){
    a=a.slice().sort(function(x,y){
      var dn=(y.n||1)-(x.n||1);
      if(dn)return dn;
      return (x.t||0)-(y.t||0);
    }).slice(0,WEAK_CAP);
  }
  try{safeSet('bt_qa_weak',JSON.stringify(a));}catch(e){}
}
/* P1-2：同一题（type + q 相同）只留一条，重复错只累加次数 n 与最后时间 t */
function addWeak(item){
  if(!item||!item.q)return;
  var a=loadWeak(),ex=null,i;
  for(i=0;i<a.length;i++){if(a[i]&&a[i].type===item.type&&a[i].q===item.q){ex=a[i];break;}}
  if(ex){
    ex.n=(ex.n||1)+1;ex.t=Date.now();
    srsAdvance(ex,false);   /* C2：已有记录再答错 → 重置复习间隔（明天再复习） */
    if(item.pick)ex.pick=item.pick;
    if(!ex.a&&item.a)ex.a=item.a;
    if(!ex.opts&&item.opts)ex.opts=item.opts.slice();
    if(!ex.code&&item.code)ex.code=item.code;
    if(!ex.exp&&item.exp)ex.exp=item.exp;
    if(!ex.sol&&item.sol)ex.sol=item.sol;
    if(!ex.steps&&item.steps)ex.steps=item.steps;
    if(ex.diff==null&&item.diff!=null)ex.diff=item.diff;
    if(!ex.tag&&item.tag)ex.tag=item.tag;
  }else{
    a.push({n:1,t:Date.now(),type:item.type,diff:item.diff,q:item.q,a:item.a,
      opts:item.opts?item.opts.slice():null,code:item.code,exp:item.exp,sol:item.sol,steps:item.steps,
      fillin:item.fillin,pick:item.pick||null,src:item.src||null,tag:item.tag||'',srs:srsInit()});
  }
  saveWeak(a);
}
/* 移除：口径与去重一致（type + q），不再要求 a 也相同 —— 老记录 a 可能为空 */
function removeWeak(item){
  if(!item)return;
  var a=loadWeak().filter(function(x){return !(x&&x.type===item.type&&x.q===item.q)});
  saveWeak(a);
}
function getRank(bk){var ds=qaDiffs(bk);if(!ds)return -1;var n=ds.length;var def=(bk==='math')?1:0;var sv=parseInt(S.getItem('bt_qa_rank_'+bk),10);return (sv>=0&&sv<n)?sv:def}
function setRank(bk,r){try{safeSet('bt_qa_rank_'+bk,r)}catch(e){}}
function genNextAuto(){var _bk=(typeKey&&typeKey.indexOf('b:')===0)?typeKey.slice(2):'';var T=QA_TYPES[_bk];if(!T)return{q:'',a:'',opts:['']};var arr=T.gen(1,selfRank);return (arr&&arr.length)?arr[0]:{q:'',a:'',opts:['']}}
function pickPoolByDiff(pool,diff){if(!pool)return [];
 var out;
 if(!Array.isArray(pool)){var g0=pool[String(diff==null?0:diff)];if(!Array.isArray(g0))g0=pool['0'];if(!Array.isArray(g0))g0=pool[0];out=Array.isArray(g0)?g0:[]}
 else if(pool.length&&Array.isArray(pool[0])&&Array.isArray(pool[0][0])){var g1=pool[diff]||pool[0];out=Array.isArray(g1)?g1:[]}
 else out=pool;
 /* P0-1：否定式题（不包括/不属于/…）没有定制干扰项就直接不出 ——
    随机补出来的选项必然有多个都成立，是「多选题当单选做」的根源。 */
 return out.filter(function(it){
   return !(it&&NEG_Q_RE.test(String(it[0]))&&!(it[3]||it.opts));
 });}
function fallbackWrongs(ans){return QALogic.fallbackWrongs(ans)}
function ansClass(s){return QALogic.ansClass(s)}
/* P0-1：否定式题干（「不包括 / 不属于 / 以下哪个不是 …」）。
   这类题没有定制干扰项时随机补选项 ⇒ 多个选项都可能成立（多解），一律不许兜底。 */
var NEG_Q_RE=/不包括|不属于|以下哪个不是|以下哪项不是|错误的是|不正确的是|不正确的|不是.*的是/;
function mkFromPool(item,pool){var ans=String(item[1]),seen={};seen[ans]=1;var ws=[];
 /* P0-1：定制干扰项优先（item[3] 管道串 / item.opts） */
 var custom=item[3]||item.opts;
 if(custom){
  var srcArr=Array.isArray(custom)?custom.map(function(x){return String(x);}):String(custom).split('|');
  srcArr.forEach(function(w){w=String(w).trim();if(ws.length>=3)return;if(!w||seen[w])return;seen[w]=1;ws.push(w)});
 }
 /* P0-1：没有定制干扰项时，只允许非否定题走随机兜底 —— 否定题随机补选项必然多解 */
 if(ws.length<3&&!NEG_Q_RE.test(String(item[0]))){
  var cls=ansClass(ans),pref=[],rest=[];
  shuffle(pool.slice()).forEach(function(p){var w=String(p[1]);if(w===ans||seen[w])return;if(p===item)return;(ansClass(w)===cls?pref:rest).push(w)});
  /* 长度相近的优先：同类且字数接近，才不像「首都→屈原」这种明显异物 */
  function lenGap(w){return Math.abs(String(w).length-ans.length);}
  pref.sort(function(a,b){return lenGap(a)-lenGap(b);});
  pref.concat(rest).forEach(function(w){if(ws.length>=3)return;if(seen[w])return;seen[w]=1;ws.push(w)});
 }
 fallbackWrongs(ans).forEach(function(w){if(ws.length>=3)return;if(seen[w])return;seen[w]=1;ws.push(w)});
 var o={q:item[0],a:ans,opts:shuffle([ans].concat(ws))};
 /* C1：解析与来源透传 —— 数组第 5 元素 meta 与对象字段两种写法都兼容（sol/steps 顺带，手写题以后用得上） */
 if(item[4]&&item[4].exp)o.exp=item[4].exp;
 if(item.exp)o.exp=item.exp;
 if(item[4]&&item[4].src)o.src=item[4].src;
 if(item.src)o.src=item.src;
 if(item[4]&&item[4].sol)o.sol=item[4].sol;
 if(item[4]&&item[4].steps)o.steps=item[4].steps;
 /* 兜底出来的题干扰项质量不可控，打标记方便后台筛出来返修 */
 if(!custom)o.review=false;
 return o}
/* P0-2：无放回抽样 —— 池子不够就只出 src.length 题，绝不复用凑数（题量不足由调用方/UI 提示兜底） */
function genPool(n,pool,diff){
 var src=pickPoolByDiff(pool,diff);
 var take=Math.min(n,src.length);
 return shuffle(src).slice(0,take).map(function(it){return mkFromPool(it,src);});
}
/* P0-2：手写题一局内去重用的「本轮已出」集合（在 doStartType 重置） */
var _handUsed=[];
var SUPMAP={0:'⁰',1:'¹',2:'²',3:'³',4:'⁴',5:'⁵',6:'⁶',7:'⁷',8:'⁸',9:'⁹','-':'⁻'};
function supNum(v){return String(v).split('').map(function(c){return SUPMAP[c]||c}).join('')}
function xpow(c,e){return c+'x'+(e===1?'':supNum(e))}
function neighbors(ans,extra){var num=Number(ans),c=[];
 if(isFinite(num)&&String(num)===String(ans).trim()){[1,-1,2,-2,3,-3].forEach(function(d){c.push(String(num+d))})}
 else{c=['以上都不对','不确定','其他答案']}
 (extra||[]).forEach(function(x){c.push(String(x))});return c}
function mkQA(q,ans,cands,exp){ans=String(ans);var seen={};seen[ans]=1;var ws=[];
 /* ⚠ 别把字面量 'NaN' 当脏选项丢掉：有些题它本身就是合法选项（如 0.1+0.2===0.3 的结果），
    丢掉会让这道题只剩 3 个选项。真空值只可能是 undefined / 空串。 */
 shuffle(cands.slice()).forEach(function(w){w=String(w);if(ws.length>=3)return;if(w===''||w==='undefined'||seen[w])return;seen[w]=1;ws.push(w)});
 /* 参数巧合导致干扰项不足时，数值答案用邻居补足（保持 4 选项，不塌成 3 个） */
 if(ws.length<3){QALogic.numericNeighbors(ans,seen,3-ws.length).forEach(function(w){ws.push(w);});}
 return {q:q,a:ans,opts:shuffle([ans].concat(ws)),exp:exp||''}}
/* P0-1 校验：统一判「这道题能不能教错人」。
   两种来源都能判：
   - 源静态题：item[3] 是 3 个干扰项的管道串（不含答案），要求 3 个、唯一、且不含答案；
   - 运行时题：q.opts 是 4 个选项（含答案），要求 4 个、唯一、且含答案（AI / 生成题走这条）。
   任一通过即视为合格（4 选项含答案，或 3 干扰项不含答案）。 */
/* P0-1 校验：全站统一闸门，实现已抽到 src/logic.js（Node 单测覆盖）。
   源静态题 = item[3] 三个干扰项（不含答案）；运行时题 = it.opts 四选项（含答案）；
   非选择题（fill/calc/experiment）只要题干与答案非空；缺省 type 按选择题走老逻辑。 */
function validItem(it){return QALogic.validItem(it)}
function genMathPrimary(n){var out=[];for(var i=0;i<n;i++){var t=ri(4),a,b,ans,q,exp;
 if(t===0){a=ri(15)+1;b=ri(Math.max(1,20-a))+1;ans=a+b;q=a+' + '+b+' = ?';exp='把 '+a+' 和 '+b+' 合起来，得到 '+ans}
 else if(t===1){a=ri(18)+2;b=ri(a-1)+1;ans=a-b;q=a+' − '+b+' = ?';exp='从 '+a+' 里去掉 '+b+'，还剩 '+ans}
 else if(t===2){a=ri(8)+2;b=ri(8)+2;ans=a*b;q=a+' × '+b+' = ?';exp=a+' 个 '+b+' 相加（'+b+' 的 '+a+' 倍），得 '+ans}
 else{b=ri(8)+2;ans=ri(8)+2;a=b*ans;q=a+' ÷ '+b+' = ?';exp='因为 '+b+' × '+ans+' = '+a+'，所以 '+a+' ÷ '+b+' = '+ans}
 var c=neighbors(ans).filter(function(x){return Number(x)>=0});
 if(c.length<3){c=['1','2','3'].filter(function(x){return x!==String(ans)})}
 out.push(mkQA(q,ans,c,exp))}
 return out}
function genMathJunior(n){var out=[];for(var i=0;i<n;i++){var t=ri(6),a,b,ans,q,exp;
 if(t===0){a=ri(60)+20;b=ri(60)+20;ans=a+b;q=a+' + '+b+' = ?';exp='两位数相加：个位加个位、十位加十位，得 '+ans}
 else if(t===1){a=ri(70)+30;b=ri(a-10)+1;ans=a-b;q=a+' − '+b+' = ?';exp='列竖式相减，'+a+' − '+b+' = '+ans}
 else if(t===2){a=ri(80)+11;b=ri(8)+2;ans=a*b;q=a+' × '+b+' = ?';exp='把 '+b+' 拆成整十数加零头分别相乘再相加，得 '+ans}
 else if(t===3){a=ri(41)-20;b=ri(41)-20;ans=a+b;q='（'+a+'）+（'+b+'）= ?';exp='带符号相加，同号取绝对值相加、异号取绝对值相减，得 '+ans}
 else if(t===4){a=ri(41)-20;b=ri(41)-20;ans=a-b;q='（'+a+'）−（'+b+'）= ?';exp='减去一个数等于加上它的相反数：'+a+' + ('+(-b)+') = '+ans}
 else{if(ri(2)){a=-(ri(19)+1);ans=Math.abs(a);q='|'+a+'| = ?';exp='绝对值只去掉符号、不看正负，|'+a+'| = '+ans}else{a=ri(14)+2;ans=a*a;q=a+'² = ?';exp='平方就是自己乘自己：'+a+' × '+a+' = '+ans}}
 out.push(mkQA(q,ans,neighbors(ans,[String(-Number(ans))]),exp))}
 return out}
function genMathSenior(n){var out=[];for(var i=0;i<n;i++){var t=ri(4),a,b,ans,q,c,exp;
 if(t===0){a=ri(9)+1;b=ri(9)+1;ans=(a+b)*(a+b);q='（'+a+' + '+b+'）² = ?';c=neighbors(ans,[String(a*a+b*b)]);exp='先算括号：'+a+' + '+b+' = '+(a+b)+'，再平方得 '+ans}
 else if(t===1){var m=ri(199)+2;ans=Math.round(Math.sqrt(m));q='√'+m+' 最接近哪个整数？';c=neighbors(ans);exp=ans+'² = '+(ans*ans)+'，与 '+m+' 最接近'}
 else if(t===2){var x=ri(19)-9;if(x===0)x=3;a=ri(8)+2;b=ri(20)+1;var cc=a*x+b;ans=x;q='解方程 '+a+'x + '+b+' = '+cc+'，x = ?';c=neighbors(ans,[String(-x)]);exp='移项得 '+a+'x = '+(cc-b)+'，两边同除以 '+a+'，x = '+x}
 else{var k=ri(9)+1;ans=k;q='log₂（'+Math.pow(2,k)+'）= ?';c=neighbors(ans);exp='2 的 '+k+' 次方是 '+Math.pow(2,k)+'，所以对数值是 '+k}
 out.push(mkQA(q,ans,c,exp))}
 return out}
function genMathCollege(n){var out=[];for(var i=0;i<n;i++){var t=ri(4),ans,q,c,exp;
 if(t===0){var e=ri(5)+2;ans=xpow(e,e-1);q='d/dx（x'+supNum(e)+'）= ?';c=[xpow(e-1,e-1),xpow(e+1,e),xpow(e,e),xpow(e*2,e-1)];exp='幂函数求导：指数移到系数、指数减一，得 '+ans}
 else if(t===1){var p=ri(4)+1;ans='x'+supNum(p+1)+'/'+(p+1);q='∫ x'+supNum(p)+' dx 的一个原函数是？';c=['x'+supNum(p+1)+'/'+p,'x'+supNum(p)+'/'+(p+1),'x'+supNum(p+2)+'/'+(p+1),'x'+supNum(p+1)+'/'+p];exp='积分指数加一、再除以新指数，得 '+ans}
 else if(t===2){var arr=[['sin(0)','0'],['cos(0)','1'],['sin(π/2)','1'],['cos(π/2)','0'],['sin(π)','0'],['cos(π)','-1']];var it=arr[ri(arr.length)];q=it[0]+' 的值是？';ans=it[1];c=['0','1','-1','√2/2','1/2'];exp='单位圆上该角的纵/横坐标就是它，'+it[0]+' = '+ans}
 else{var tab=[['sin(π/6)','1/2'],['cos(π/3)','1/2'],['sin(π/3)','√3/2'],['cos(π/6)','√3/2'],['tan(π/4)','1'],['sin(π/4)','√2/2'],['cos(π/4)','√2/2'],['tan(π/6)','√3/3'],['tan(π/3)','√3']];var it2=tab[ri(tab.length)];q=it2[0]+' 的值是？';ans=it2[1];c=['1/2','√2/2','√3/2','√3/3','√3','1','0'];exp=it2[0]+' 是特殊角，其值为 '+ans}
 out.push(mkQA(q,ans,c,exp))}
 return out}
function genMath(n,diff){var d=(typeof diff==='number'&&diff>=0)?diff:0;
 if(d===1)return genMathJunior(n);if(d===2)return genMathSenior(n);if(d>=3)return genMathCollege(n);
 return genMathPrimary(n)}
