function safeDecodeURI(s){s=String(s==null?'':s);try{return decodeURIComponent(s)}catch(e){try{return decodeURIComponent(s.replace(/%(?![0-9a-fA-F]{2})/g,'%25'))}catch(e2){return s}}}
